SELECT 
FROM pos_terminal t



        (t.code LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%'))

    AND t.store_id = #{storeId}
    AND t.status = #{status}

ORDER BY t.store_id, t.sort, t.id

SELECT 
FROM pos_terminal t

WHERE t.id = #{id}

SELECT COALESCE(SUM(s.qty - s.frozen_qty), 0)
FROM wms_stock s
WHERE s.warehouse_id = #{warehouseId} AND s.material_id = #{materialId}
